CREATE TABLE v8_output_artifacts (artifact_id TEXT PRIMARY KEY, artifact_family TEXT, title_snapshot TEXT, origin_summary_json TEXT);
CREATE TABLE report_builder_templates (id TEXT PRIMARY KEY, organization_id TEXT, name TEXT, description TEXT, updated_at TIMESTAMPTZ);
CREATE TABLE presentation_templates (id TEXT PRIMARY KEY, organization_id TEXT, name TEXT, description TEXT, updated_at TIMESTAMPTZ);
CREATE TABLE document_studio_templates (template_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT, purpose TEXT, language TEXT);
CREATE TABLE tp_base_templates (id SERIAL PRIMARY KEY, name TEXT, description TEXT, created_by TEXT);
